const a=[["有利帧","Frame Advantage","双方恢复行动的时间差。+2 表示你早 2 帧行动，不代表任何招式都能继续压制；还要看发生、距离、取消与无敌属性。"],["发生","Startup","动作开始到首次攻击判定出现所需的帧数；数字越小通常出手越快。"],["收招","Recovery","攻击判定结束后的恢复阶段。挥空时对手可抓这个阶段，能否惩罚取决于距离与反应时间。"],["帧数陷阱","Frame Trap","在防御串中留一个小空档，让对手普通攻击能启动却来不及打中，就被后续攻击打断。无敌技等选项要另测。"],["距离陷阱","Spacing Trap","自己的招式被防后，利用推远的间距使对方回击挥空，再惩罚收招。不是所有负帧招式都能这样用。"],["立回策略","Neutral","尚未形成稳定压制时，通过移动、牵制、对空和观察争取有利位置与命中机会。并非每一种立回策略都是陷阱。"],["起身设置","Okizeme","击倒后安排站位与动作，针对对手起身选项施压。要注明收尾、实际优势、位置、受身与角色状态。"],["压起身","Meaty","让攻击判定覆盖对手起身可被打中的时刻；若以招式较晚的判定接触，还可能获得更好的帧数优势。"],["安全跳","Safe Jump","跳攻击压起身，对手防御时形成压制；对特定无敌反击，则能及时落地防御。不是对所有反击都安全。"],["挥空","Whiff","攻击没有碰到对手。可能是失误、诱饵，也可能是设置中用于消耗固定时间的动作。"],["差合","Whiff Punish","抓对手攻击挥空后的收招，用够得到且来得及的攻击惩罚。"],["差入","Poke","主动进入有效距离，以拳脚攻击对手的移动或空隙；这里用作主动地面攻击的教学标签，中文用法并不完全统一。"],["置技（先置）","Preemptive","预判对手前进或出招，提前把攻击判定放到预计位置；不是看到挥空后才反应，也不是设置机关。"],["确反","Punish","对手恢复行动前无法防住的惩罚。负帧只是条件之一，还须考虑己方发生与攻击距离。"],["惩罚康（PC）","Punish Counter","在游戏规定的可惩罚阶段命中触发的状态。与普通康（Counter Hit）不同，也不能将所有 PC 简单等同于被防确反。"],["连防","Blockstring","这里特指无可行动空档的连续防御段；与故意留空档抓按键的帧数陷阱区分。"],["确认","Hit Confirm","判断攻击命中还是被防，再选择继续连段或停止，避免盲目打出危险收尾。"],["空挥计时","Frame Kill","有意使用固定耗时动作消耗优势，让后续时机更容易重复；必须记录动作与输入时机。"],["投诱（Shimmy）","Shimmy","在投的威胁下后退，诱使对手拆投或投技挥空，再惩罚。不是所有后退诱空都叫 Shimmy。"],["取消","Cancel","在允许的窗口把当前动作接入另一动作；不等于等待收招结束后连接，招式的取消权限各不相同。"]].map(([r,e,t])=>({term:r,english:e,description:t,sourceUrl:`https://glossary.infil.net/?t=${encodeURIComponent(e)}`}));export{a as g};
